import json
import os
import sys
from datetime import datetime

def normalize_date(s):
    """Convert a date string to YYYY-MM-DD if possible."""
    s = s.strip()
    if not s:
        return None
    # Already in YYYY-MM-DD format
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    # YYYYMMDD format
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    # Fallback: try parsing
    try:
        dt = datetime.strptime(s, "%Y%m%d")
        return dt.strftime("%Y-%m-%d")
    except Exception:
        return s

def get_field_value(record, field):
    """Extract a non-empty field value from a record, or None."""
    if field not in record:
        return None
    val = record[field]
    if val is None:
        return None
    if isinstance(val, str):
        val = val.strip()
        if val == "":
            return None
    else:
        val = str(val)
    return val

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Load the FDA enforcement reports file
    fda_filename = "fda_enforcement_reports.json"
    fda_file = os.path.join(packet_dir, fda_filename)
    with open(fda_file) as f:
        data = json.load(f)
    records = data.get("results", [])

    # Index records by recall_number
    index = {}
    for rec in records:
        rn = rec.get("recall_number")
        if rn:
            index.setdefault(rn, []).append(rec)

    doc_name = os.path.splitext(fda_filename)[0]

    # Mapping from (rule_id, fact_name) to (field_name, document)
    fact_map = {
        ("fda.classified_30d", "initiation date"): ("recall_initiation_date", doc_name),
        ("fda.classified_30d", "classification date"): ("center_classification_date", doc_name),
        ("fda.terminated_180d", "initiation date"): ("recall_initiation_date", doc_name),
        ("fda.terminated_180d", "termination date"): ("termination_date", doc_name),
    }

    date_fields = {"recall_initiation_date", "center_classification_date", "termination_date"}

    output = {}
    for pair in manifest.get("pairs", []):
        parts = pair.split("::")
        if len(parts) != 2:
            continue
        rule_id, entity = parts
        facts = manifest.get("facts", {}).get(rule_id, [])
        result_obj = {}
        for fact in facts:
            key = (rule_id, fact)
            if key not in fact_map:
                result_obj[fact] = "ABSENT"
                continue
            field, doc = fact_map[key]
            recs = index.get(entity, [])
            values = []
            for rec in recs:
                val = get_field_value(rec, field)
                if val is not None:
                    if field in date_fields:
                        val = normalize_date(val)
                    values.append(val)
            if not values:
                result_obj[fact] = "ABSENT"
            elif len(set(values)) == 1:
                result_obj[fact] = [values[0], doc]
            else:
                result_obj[fact] = "CONFLICT"
        output[pair] = result_obj

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
