def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load all JSON files in the packet directory
    documents = {}
    for fname in os.listdir(packet_dir):
        if fname.endswith(".json"):
            doc_name = os.path.splitext(fname)[0]
            file_path = os.path.join(packet_dir, fname)
            try:
                documents[doc_name] = load_records(file_path)
            except Exception:
                pass

    # Index records by recall_number for each document
    doc_index = {}
    for doc_name, records in documents.items():
        index = {}
        for r in records:
            rn = r.get("recall_number")
            if rn is not None:
                index.setdefault(rn, []).append(r)
        doc_index[doc_name] = index

    output = {}
    for pair in manifest.get("pairs", []):
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])
        result_obj = {}

        if rule_id in RULES:
            for fact in facts:
                if fact in RULES[rule_id]:
                    doc_name, field = RULES[rule_id][fact]
                    matching = doc_index.get(doc_name, {}).get(entity, [])
                    values = []
                    for r in matching:
                        val = r.get(field, "")
                        if val:
                            normalized = normalize_date(val)
                            if normalized is not None:
                                values.append(normalized)
                    if not values:
                        result_obj[fact] = "ABSENT"
                    elif len(set(values)) == 1:
                        result_obj[fact] = [values[0], doc_name]
                    else:
                        result_obj[fact] = "CONFLICT"
                else:
                    result_obj[fact] = "ABSENT"
        else:
            for fact in facts:
                result_obj[fact] = "ABSENT"

        output[pair] = result_obj

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

