            field = fact_to_field.get(fact_name)
            if field is None:
                result_obj[fact_name] = "ABSENT"
                continue
            values = []
            for rec in records:
                raw = rec.get(field, "")
                if raw:
                    parsed = parse_date(raw)
                    if parsed:
