            elif len(set(values)) == 1:
                result_obj[fact_name] = [values[0], "fda_enforcement_reports"]
            else:
                result_obj[fact_name] = "CONFLICT"
        output[pair] = result_obj

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
