calls.reply:
Looking at this problem, I need to:

1. Read the manifest to get pairs (rule_id::entity) and facts per rule
2. Load the FDA enforcement reports JSON and index records by `recall_number`
3. For each pair, extract the relevant fields for each fact
4. Handle date conversion (YYYYMMDD → YYYY-MM-DD), ABSENT (empty), and CONFLICT (disagreeing values)

Key observations:
- The entity in each pair is the `recall_number` (e.g., "F-0159-2023")
- Fact fields map to: `initiation date`→`recall_initiation_date`, `classification date`→`center_classification_date`, `termination date`→`termination_date`
- Empty strings mean ABSENT; multiple matching records with different non-empty values mean CONFLICT
- The document name is the filename without extension: `fda_enforcement_reports`

```python
import json
import os
import sys

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Load all JSON files in the packet directory, keyed by name without extension
    documents = {}
    for fname in os.listdir(packet_dir):
        if fname.endswith(".json"):
            doc_name = fname[:-5]
            with open(os.path.join(packet_dir, fname)) as fh:
                documents[doc_name] = json.load(fh)

    fda_doc = documents.get("fda_enforcement_reports", {})
    records = fda_doc.get("results", []) if isinstance(fda_doc, dict) else []

    # Index records by recall_number
    by_recall = {}
    for rec in records:
        if not isinstance(rec, dict):
            continue
        rn = rec.get("recall_number", "")
        by_recall.setdefault(rn, []).append(rec)

    fact_fields = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date",
    }

    def fmt_date(s):
        s = str(s).strip()
        if len(s) == 8 and s.isdigit():
            return f"{s[0:4]}-{s[4:6]}-{s[6:8]}"
        return s

    output = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts_for_rule = manifest["facts"].get(rule_id, [])
        result = {}
        matching = by_recall.get(entity, [])
        for fact_name in facts_for_rule:
            field = fact_fields.get(fact_name)
            if field is None:
                result[fact_name] = "ABSENT"
                continue
            values = []
            for rec in matching:
                v = rec.get(field, "")
                if v is None:
                    continue
                v = str(v).strip()
                if v != "":
                    values.append(v)
            if not values:
                result[fact_name] = "ABSENT"
            else:
                normalized = [fmt_date(v) for v in values]
                unique = set(normalized)
                if len(unique) == 1:
                    result[fact_name] = [normalized[0], "fda_enforcement_reports"]
                else:
                    result[fact_name] = "CONFLICT"
        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
```

